1→import assert from 'node:assert/strict';
2→import { mkdtempSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
3→import { tmpdir } from 'node:os';
4→import { join } from 'node:path';
5→import test from 'node:test';
6→import { AtlasCpgSlice, AtlasCpgTaint } from '../src/index.mjs';
7→
8→const dir = (name) => mkdtempSync(join(tmpdir(), `baton-${name}-`));
9→function fixture(source, opts = {}) {
10→  const root = dir('path-cpg-root'); const artifacts = dir('path-cpg-artifacts');
11→  mkdirSync(join(root, 'src'), { recursive: true }); writeFileSync(join(root, 'src/a.js'), source);
12→  const common = { maxSourceBytes: 64 * 1024, maxReachDefPairs: 128, ...opts };
13→  const cpg = new AtlasCpgSlice({ artifactRoot: join(artifacts, 'cpg'), maxArtifactBytes: 512 * 1024, ...common });
14→  const taint = new AtlasCpgTaint({ artifactRoot: join(artifacts, 'taint'), maxGraphBytes: 512 * 1024, maxResultBytes: 512 * 1024, maxDepth: 24, maxPaths: 32, ...common });
15→  return { root, artifacts, cpg, taint, ctx: { root, budgetTokens: 10000 }, args: { path: 'src/a.js', sourceNames: ['readInput'], sinkNames: ['send'], depth: 20 } };
16→}
17→
18→async function graph(f) {
19→  const result = await f.cpg.invoke('cpg.build', { path: 'src/a.js' }, f.ctx);
20→  return JSON.parse(readFileSync(result.refs[0].path, 'utf8'));
21→}
