23→test('PS1: a braced if/else enters both branches and both non-terminal tails join the follower', async () => {
24→  const f = fixture(`function run(flag) {
25→  if (flag) {
26→    left()
27→  } else {
28→    right()
29→  }
30→  done()
31→}\n`);
32→  const g = await graph(f);
33→  const statement = (line) => g.nodes.find((node) => node.type === 'statement' && node.range.start.line === line);
34→  const branch = statement(2); const left = statement(3); const right = statement(5); const done = statement(7);
35→  assert.ok(branch && left && right && done);
36→  assert.ok(g.edges.some((edge) => edge.type === 'CFG_TRUE' && edge.from === branch.id && edge.to === left.id));
37→  assert.ok(g.edges.some((edge) => edge.type === 'CFG_FALSE' && edge.from === branch.id && edge.to === right.id));
38→  assert.ok(g.edges.some((edge) => edge.type === 'CFG_NEXT' && edge.from === left.id && edge.to === done.id));
39→  assert.ok(g.edges.some((edge) => edge.type === 'CFG_NEXT' && edge.from === right.id && edge.to === done.id));
40→  assert.equal(g.edges.some((edge) => edge.type === 'CFG_NEXT' && edge.from === branch.id && edge.to === done.id), false);
41→});
