43→test('PS2/PS4: alternate branch definitions may reach a join but literal-dead sources and sinks do not', async () => {
44→  const may = fixture(`function readInput(){} function safe(){} function send(v){}
45→function run(flag){ let value=readInput(); if(flag){ value=safe() } send(value) }\n`);
46→  const possible = await may.taint.invoke('cpg.taint', may.args, may.ctx);
47→  assert.equal(possible.payload.length, 1, 'the pre-branch source definition reaches the sink on the false path');
48→
49→  const deadDefinition = fixture(`function readInput(){} function send(v){}
50→function run(){ let value; if(false){ value=readInput() } send(value) }\n`);
51→  assert.equal((await deadDefinition.taint.invoke('cpg.taint', deadDefinition.args, deadDefinition.ctx)).payload.length, 0);
52→
53→  const deadDirect = fixture(`function readInput(){} function send(v){}
54→function run(){ if(false){ send(readInput()) } }\n`);
55→  assert.equal((await deadDirect.taint.invoke('cpg.taint', deadDirect.args, deadDirect.ctx)).payload.length, 0);
56→});
