58→test('PS3/PS4: direct identifier copies carry value while a nested sanitizer cannot be bypassed', async () => {
59→  const copied = fixture(`function readInput(){} function send(v){}
60→function run(){ let a=readInput(); let b=a; send(b) }\n`);
61→  const copyResult = await copied.taint.invoke('cpg.taint', copied.args, copied.ctx);
62→  assert.equal(copyResult.payload.length, 1);
