85→  assert.equal((await heap.taint.invoke('cpg.taint', heap.args, heap.ctx)).payload.length, 0);
86→  const returned = fixture(`function readInput(){} function wrap(){ return readInput() } function send(v){} function run(){ send(wrap()) }\n`);
87→  assert.equal((await returned.taint.invoke('cpg.taint', returned.args, returned.ctx)).payload.length, 0);
