97→  const f = fixture(`function readInput(){} function safe(){} function send(v){}\nfunction run(flag){
98→  let value
99→  if(flag === 1){
100→    value=safe()
101→  } else if(flag === 2){
102→    value=readInput()
103→  } else {
104→    value=safe()
105→  }
106→  send(value)
107→}\n`);
108→  const g = await graph(f); const branches = g.nodes.filter((node) => node.type === 'statement' && node.kind === 'if_statement').sort((a, b) => a.range.start.line - b.range.start.line);
109→  assert.equal(branches.length, 2);
