117→  const possible = fixture(`function readInput(){} function send(v){}\nfunction run(flag){ let value; try { if(flag){ value=readInput() } } catch {} send(value) }\n`);
118→  assert.equal((await possible.taint.invoke('cpg.taint', possible.args, possible.ctx)).payload.length, 1);
119→  const dead = fixture(`function readInput(){} function send(v){}\nfunction run(){ let value; try { if(false){ value=readInput() } } catch {} send(value) }\n`);
120→  assert.equal((await dead.taint.invoke('cpg.taint', dead.args, dead.ctx)).payload.length, 0);
