import { mkdtempSync, mkdirSync, writeFileSync, readFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { AtlasCpgSlice, AtlasCpgTaint, AtlasCpgDelta } from './impl/src/index.mjs';

const dir = (n) => mkdtempSync(join(tmpdir(), `adv-${n}-`));
async function build(source, opts={}) {
  const root = dir('r'); const artifacts = dir('a');
  mkdirSync(join(root,'src'),{recursive:true}); writeFileSync(join(root,'src/a.js'), source);
  const cpg = new AtlasCpgSlice({ artifactRoot: join(artifacts,'cpg'), maxSourceBytes: 64*1024, maxArtifactBytes: 512*1024, maxReachDefPairs: 128, ...opts });
  const taint = new AtlasCpgTaint({ artifactRoot: join(artifacts,'taint'), maxSourceBytes: 64*1024, maxGraphBytes: 512*1024, maxResultBytes: 512*1024, maxDepth: 24, maxPaths: 32, maxReachDefPairs: 128, ...opts });
  const result = await cpg.invoke('cpg.build', {path:'src/a.js'}, {root, budgetTokens: 20000});
  const g = JSON.parse(readFileSync(result.refs[0].path,'utf8'));
  return {root, artifacts, cpg, taint, g, result, ctx:{root, budgetTokens:20000}};
}
function stmt(g,line){return g.nodes.find(n=>n.type==='statement'&&n.range.start.line===line)}
function edgesOf(g,type){return g.edges.filter(e=>e.type===type)}
function showCfg(g){
  const byId=Object.fromEntries(g.nodes.map(n=>[n.id,n]));
  return g.edges.filter(e=>['CFG_ENTRY','CFG_NEXT','CFG_TRUE','CFG_FALSE','CFG_EXIT'].includes(e.type)).map(e=>{
    const f=byId[e.from], t=byId[e.to];
    const fl=f?.range?.start?.line??f?.type; const tl=t?.range?.start?.line??t?.type;
    return `${e.type} L${fl}:${f?.kind||f?.type} -> L${tl}:${t?.kind||t?.type}`;
  });
}

const cases = [];

// 1 mixed braces
{
  const {g} = await build(`function run(flag){\n  if (flag) {\n    left()\n  } else right()\n  done()\n}\n`);
  const branch = stmt(g,2);
  const structured = g.edges.some(e=>e.type==='CFG_TRUE'&&e.from===branch?.id);
  cases.push(['mixed brace if/else is structured?', structured, showCfg(g)]);
}

// 2 literal true omits false
{
  const {g} = await build(`function run(){\n  if (true) {\n    left()\n  } else {\n    right()\n  }\n  done()\n}\n`);
  const branch=stmt(g,2), right=stmt(g,5), left=stmt(g,3), done=stmt(g,7);
  cases.push(['literal true: no CFG_FALSE', !g.edges.some(e=>e.type==='CFG_FALSE'&&e.from===branch.id)]);
  cases.push(['literal true: CFG_TRUE to left', g.edges.some(e=>e.type==='CFG_TRUE'&&e.from===branch.id&&e.to===left.id)]);
  cases.push(['right cfgReachable false', right.cfgReachable===false]);
  cases.push(['left cfgReachable true', left.cfgReachable===true]);
}

// 3 literal false omits true
{
  const {g} = await build(`function run(){\n  if (false) {\n    left()\n  }\n  done()\n}\n`);
  const branch=stmt(g,2), left=stmt(g,3), done=stmt(g,5);
  cases.push(['literal false: no CFG_TRUE', !g.edges.some(e=>e.type==='CFG_TRUE'&&e.from===branch.id)]);
  cases.push(['literal false: CFG_FALSE to join/done', g.edges.some(e=>e.type==='CFG_FALSE'&&e.from===branch.id&&e.to===done.id)]);
  cases.push(['left dead', left.cfgReachable===false]);
}

// 4 unbraced atomic
{
  const {g} = await build(`function run(flag){\n  if (flag) left()\n  done()\n}\n`);
  const branch=stmt(g,2);
  cases.push(['unbraced no CFG_TRUE/FALSE', !g.edges.some(e=>(e.type==='CFG_TRUE'||e.type==='CFG_FALSE')&&e.from===branch.id)]);
  cases.push(['unbraced has CFG_NEXT fallthrough', g.edges.some(e=>e.type==='CFG_NEXT'&&e.from===branch.id)]);
}

// 5 nested if join
{
  const {g} = await build(`function run(a,b){\n  if (a) {\n    if (b) {\n      x()\n    }\n  }\n  done()\n}\n`);
  cases.push(['nested if cfg', showCfg(g)]);
}

// 6 bare block inside if
{
  const {g,taint,ctx} = await build(`function readInput(){} function send(v){}\nfunction run(flag){\n  let value\n  if (flag) {\n    {\n      value = readInput()\n    }\n  }\n  send(value)\n}\n`);
  const assign = g.nodes.find(n=>n.type==='identifier'&&n.role==='definition'&&n.name==='value'&&n.range.start.line>=5);
  const defs = g.nodes.filter(n=>n.type==='identifier'&&n.role==='definition'&&n.name==='value');
  const reaches = g.edges.filter(e=>e.type==='REACHING_DEF'&&defs.some(d=>d.id===e.from));
  const tr = await taint.invoke('cpg.taint',{path:'src/a.js',sourceNames:['readInput'],sinkNames:['send'],depth:20},ctx);
  cases.push(['bare block in if: def cfgReachable', defs.map(d=>({line:d.range.start.line, reach:d.cfgReachable, anchor:d.cfgAnchor}))]);
  cases.push(['bare block in if: reach def count', reaches.length]);
  cases.push(['bare block in if: taint paths', tr.payload.length]);
}

// 7 kill across branch
{
  const {g} = await build(`function run(flag){\n  let value = 1\n  if (flag) {\n    value = 2\n  }\n  use(value)\n}\n`);
  const defs = g.nodes.filter(n=>n.type==='identifier'&&n.role==='definition'&&n.name==='value');
  const use = g.nodes.find(n=>n.type==='identifier'&&n.role==='reference'&&n.name==='value'&&n.range.start.line===6);
  const rdefs = g.edges.filter(e=>e.type==='REACHING_DEF'&&e.to===use?.id).map(e=>defs.find(d=>d.id===e.from)?.range.start.line);
  cases.push(['may reach both pre and branch defs', rdefs.sort()]);
}

// 8 true branch kill should not remove false path pre-def
{
  const {taint,ctx} = await build(`function readInput(){} function safe(){} function send(v){}\nfunction run(flag){ let value=readInput(); if(flag){ value=safe() } send(value) }\n`);
  const tr = await taint.invoke('cpg.taint',{path:'src/a.js',sourceNames:['readInput'],sinkNames:['send'],depth:20},ctx);
  cases.push(['pre-branch source reaches join', tr.payload.length]);
}

// 9 both branches define - may both reach
{
  const {g} = await build(`function run(flag){\n  let value\n  if (flag) {\n    value = 1\n  } else {\n    value = 2\n  }\n  use(value)\n}\n`);
  const defs = g.nodes.filter(n=>n.type==='identifier'&&n.role==='definition'&&n.name==='value');
  const use = g.nodes.find(n=>n.type==='identifier'&&n.role==='reference'&&n.name==='value'&&n.range.start.line===8);
  const rdefs = g.edges.filter(e=>e.type==='REACHING_DEF'&&e.to===use?.id).map(e=>{
    const d=defs.find(x=>x.id===e.from); return d?.range.start.line;
  });
  cases.push(['both branch defs reach join', rdefs.sort()]);
}

// 10 return in then does not join
{
  const {g} = await build(`function run(flag){\n  if (flag) {\n    return left()\n  } else {\n    right()\n  }\n  done()\n}\n`);
  const left=stmt(g,3), done=stmt(g,7), right=stmt(g,5);
  cases.push(['return then no NEXT to done', !g.edges.some(e=>e.from===left.id&&e.to===done.id)]);
  cases.push(['else joins done', g.edges.some(e=>e.type==='CFG_NEXT'&&e.from===right.id&&e.to===done.id)]);
}

