// Identifier copy ASSIGNED_FROM direction and no reverse
{
  const {g} = await probe(`function run(){ let a=1; let b=a; let c=b }\n`);
  console.log('copy edges', g.edges.filter(e=>e.type==='ASSIGNED_FROM').length);
}

// Sanitizer as source itself
{
  const {tr} = await probe(`function readInput(){} function send(v){}\nfunction run(){ send(readInput()) }\n`);
  // if source is also sanitizer
}
const root = dir('r'); const artifacts = dir('a');
mkdirSync(join(root,'src'),{recursive:true});
writeFileSync(join(root,'src/a.js'), `function readInput(){} function send(v){}\nfunction run(){ send(readInput()) }\n`);
const taint = new AtlasCpgTaint({ artifactRoot: join(artifacts,'taint'), maxSourceBytes: 64*1024, maxGraphBytes: 512*1024, maxResultBytes: 512*1024, maxDepth: 24, maxPaths: 32, maxReachDefPairs: 128 });
