import { mkdtempSync, mkdirSync, writeFileSync, readFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { AtlasCpgSlice, AtlasCpgTaint, AtlasCpgDelta } from './impl/src/index.mjs';

const dir = (n) => mkdtempSync(join(tmpdir(), n));
const mk = (src, opts={}) => {
  const root = dir('r'); const artifacts = dir('a');
  mkdirSync(join(root,'src'),{recursive:true}); writeFileSync(join(root,'src/a.js'),src);
  const common = { maxSourceBytes: 65536, maxReachDefPairs: 4096, ...opts };
  return { root, artifacts, cpg: new AtlasCpgSlice({ artifactRoot: join(artifacts,'c'), maxArtifactBytes: 524288, ...common }), taint: new AtlasCpgTaint({ artifactRoot: join(artifacts,'t'), maxGraphBytes: 524288, maxResultBytes: 524288, maxDepth: 24, maxPaths: 32, ...common }), ctx: { root, budgetTokens: 10000 } };
};

async function build(f) {
  const r = await f.cpg.invoke('cpg.build', { path: 'src/a.js' }, f.ctx);
  return JSON.parse(readFileSync(r.refs[0].path,'utf8'));
}

const probes = [];

// 1. if(true) omits CFG_FALSE
{
  const f = mk('function run(){ if(true){ left() } else { right() } done() }\nfunction left(){} function right(){} function done(){}');
  const g = await build(f);
  const ifs = g.nodes.filter(n=>n.type==='statement'&&n.kind==='if_statement');
  const falseEdges = g.edges.filter(e=>e.type==='CFG_FALSE'&&e.from===ifs[0].id);
  probes.push(['if(true) CFG_FALSE count', falseEdges.length, 0]);
}

// 2. if(false) omits CFG_TRUE
{
  const f = mk('function run(){ if(false){ left() } else { right() } done() }\nfunction left(){} function right(){} function done(){}');
  const g = await build(f);
  const ifs = g.nodes.filter(n=>n.type==='statement'&&n.kind==='if_statement');
  const trueEdges = g.edges.filter(e=>e.type==='CFG_TRUE'&&e.from===ifs[0].id);
  probes.push(['if(false) CFG_TRUE count', trueEdges.length, 0]);
}

// 3. if without else: CFG_FALSE to join
{
  const f = mk('function run(flag){ if(flag){ left() } done() }\nfunction left(){} function done(){}');
  const g = await build(f);
  const branch = g.nodes.find(n=>n.type==='statement'&&n.kind==='if_statement');
  const done = g.nodes.find(n=>n.type==='statement'&&n.kind==='expression_statement'&&n.range.start.line===2);
  const falseToJoin = g.edges.some(e=>e.type==='CFG_FALSE'&&e.from===branch.id&&e.to===done?.id);
  probes.push(['if-no-else CFG_FALSE to join', falseToJoin, true]);
}

// 4. unbraced if stays atomic (CFG_NEXT through if)
{
  const f = mk('function run(flag){ if(flag) left(); else right(); done() }\nfunction left(){} function right(){} function done(){}');
  const g = await build(f);
  const branch = g.nodes.find(n=>n.type==='statement'&&n.kind==='if_statement');
  const hasTrue = g.edges.some(e=>e.type==='CFG_TRUE'&&e.from===branch.id);
  const nextThrough = g.edges.some(e=>e.type==='CFG_NEXT'&&e.from===branch.id);
  probes.push(['unbraced if no CFG_TRUE', hasTrue, false]);
  probes.push(['unbraced if has CFG_NEXT', nextThrough, true]);
}

// 5. sanitizer copy chain bypass?
{
  const f = mk('function readInput(){} function sanitize(v){return v} function send(v){}\nfunction run(){ let v=readInput(); let c=sanitize(v); let b=c; send(b) }\n');
  const r = await f.taint.invoke('cpg.taint', { path:'src/a.js', sourceNames:['readInput'], sinkNames:['send'], sanitizerNames:['sanitize'], depth:20 }, f.ctx);
  probes.push(['sanitizer copy chain blocked', r.payload.length, 0]);
}

// 6. literal True (case) not pruned
{
  const f = mk('function readInput(){} function send(v){}\nfunction run(){ let v; if(True){ v=readInput() } send(v) }\n');
  const r = await f.taint.invoke('cpg.taint', { path:'src/a.js', sourceNames:['readInput'], sinkNames:['send'], depth:20 }, f.ctx);
  probes.push(['True literal may still flow (product gap)', r.payload.length >= 0, true]);
}

// 7. delta REACHING_DEF sensitivity
{
  const before = 'function run(flag){ let x=1; if(flag){ x=2 } return x }\n';
  const after = 'function run(flag){ let x=1; if(flag){ x=3 } return x }\n';
  const br = dir('b'); const ar = dir('a2'); const artifacts = dir('da');
  const w = (root,p,c)=>{ mkdirSync(join(root,'src'),{recursive:true}); writeFileSync(join(root,'src/a.js'),c); };
  w(br,'src/a.js',before); w(ar,'src/a.js',after);
  const delta = new AtlasCpgDelta({ artifactRoot: artifacts, maxSourceBytes: 65536, maxGraphBytes: 524288, maxDeltaBytes: 524288, maxImpactDepth: 8, maxReachDefPairs: 4096 });
  const res = await delta.invoke('cpg.delta', { beforePath:'src/a.js', afterPath:'src/a.js', impactDepth:4 }, { beforeRoot: br, afterRoot: ar, budgetTokens: 10000 });
  const art = JSON.parse(readFileSync(res.refs[0].path,'utf8'));
  const reachChanges = art.edgeChanges.filter(e=>e.type==='REACHING_DEF');
  probes.push(['delta REACHING_DEF edge changes', reachChanges.length > 0, true]);
}

// 8. nested else { if } block form
{
  const f = mk('function run(f){ if(f===1){ a() } else { if(f===2){ b() } } c() }\nfunction a(){} function b(){} function c(){}');
  const g = await build(f);
  const ifs = g.nodes.filter(n=>n.type==='statement'&&n.kind==='if_statement').sort((a,b)=>a.range.start.line-b.range.start.line);
  const outerFalseToInner = g.edges.some(e=>e.type==='CFG_FALSE'&&e.from===ifs[0].id&&e.to===ifs[1].id);
  probes.push(['else { if } false edge to inner if', outerFalseToInner, true]);
}

// 9. fixed point terminates on cyclic CFG? (no cycles in shipped CFG but check iterations)
{
  const f = mk('function run(a){ let b=a; let c=b; let d=c; send(d) }\nfunction send(v){}');
  const r = await f.cpg.invoke('cpg.build', { path:'src/a.js' }, f.ctx);
  probes.push(['reach def build ok', r.status, 'ok']);
}

// 10. if(true) dead else arm taint
{
  const f = mk('function readInput(){} function send(v){}\nfunction run(){ let v; if(true){ v=1 } else { v=readInput() } send(v) }\n');
  const r = await f.taint.invoke('cpg.taint', { path:'src/a.js', sourceNames:['readInput'], sinkNames:['send'], depth:20 }, f.ctx);
  probes.push(['if(true) else readInput dead', r.payload.length, 0]);
}

for (const [name, got, exp] of probes) {
  const ok = got === exp ? 'PASS' : 'FAIL';
  console.log(ok, name, JSON.stringify(got), 'expected', JSON.stringify(exp));
}
"

